// The command channel's decisions. Pure: builds the poll and ack requests,
// reads a command out of a reply, decides what to do with it, and keeps the
// set of commands already executed. Every `$` call (fetch, clock, turn.abort,
// prompt.submit) is made in register.ts.
// Contract: tools/swarmery/docs/mods-link-protocol.md, "Commands".

export const COMMANDS_PATH = '/api/link/commands'
/** How long the daemon may hold a poll open (it clamps anything above 25). */
export const POLL_WAIT_S = 25
/** A poll's own bound, past the daemon's 25 s hold: HttpInit has no timeout. */
export const POLL_TIMEOUT_MS = 28_000
/** After a failed poll (no answer, a 5xx, an unreadable reply). */
export const FAILURE_BACKOFF_MS = 3_000
/** Two polls that came back empty start at least this far apart. */
export const MIN_POLL_GAP_MS = 1_000
/** `$.prompt.submit` resolves as its turn starts; past this, the prompt is left queued. */
export const PROMPT_START_TIMEOUT_MS = 10_000
/** The exact ack message the daemon reads as "deliver again after the next turn.complete". */
export const TURN_IN_PROGRESS = 'turn in progress'
/** The daemon keeps an ack message up to 500 characters. */
export const MAX_ACK_MESSAGE = 500
/** Executed ids remembered for re-delivery, newest kept. */
export const MAX_REMEMBERED = 200

export const commandsUrl = (origin: string, sessionId: string): string =>
  `${origin}${COMMANDS_PATH}?session=${encodeURIComponent(sessionId)}&wait=${POLL_WAIT_S}`

export const ackUrl = (origin: string, id: string): string => `${origin}${COMMANDS_PATH}/${encodeURIComponent(id)}/ack`

export type PollRequest = {
  readonly method: 'GET'
  readonly headers: Record<string, string>
}

export const pollRequest = (token: string): PollRequest => ({
  method: 'GET',
  headers: { authorization: `Bearer ${token}` },
})

/**
 * What a poll's reply means for the loop:
 * - `command`: 200, a command to execute and ack, then poll again at once.
 * - `idle`: 204, nothing deliverable; poll again.
 * - `auth`: 401; re-read the token once, else stop.
 * - `off`: 503 link disabled; stop.
 * - `retry`: anything else, a timeout or no answer; back off, then poll again.
 */
export type PollOutcome = 'command' | 'idle' | 'auth' | 'off' | 'retry'

export const pollOutcome = (status: number | undefined): PollOutcome => {
  if (status === 200) return 'command'
  if (status === 204) return 'idle'
  if (status === 401) return 'auth'
  if (status === 503) return 'off'
  return 'retry'
}

/** How long to wait before the next poll, given how the last one ended and how long it took. */
export const nextPollDelay = (outcome: 'command' | 'idle' | 'retry', elapsedMs: number): number => {
  if (outcome === 'command') return 0
  if (outcome === 'retry') return FAILURE_BACKOFF_MS
  return Math.max(0, MIN_POLL_GAP_MS - Math.max(0, elapsedMs))
}

export type Command =
  | { readonly id: string; readonly kind: 'stop' }
  | { readonly id: string; readonly kind: 'prompt'; readonly text: string; readonly asUser: boolean }
  | { readonly id: string; readonly kind: 'message'; readonly to: string; readonly text: string }
  | { readonly id: string; readonly kind: 'invalid'; readonly reason: string }

const isRecord = (value: unknown): value is Readonly<Record<string, unknown>> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

const commandId = (value: unknown): string | undefined => {
  if (typeof value === 'number' && Number.isSafeInteger(value) && value > 0) return String(value)
  if (typeof value === 'string' && /^[1-9]\d{0,18}$/.test(value)) return value
  return undefined
}

/**
 * The command a 200 carries, or undefined when the reply names no id to ack
 * (the loop then backs off as on a failure). A command it cannot run comes
 * back `invalid`, to be acked failed.
 */
export const parseCommand = (text: unknown): Command | undefined => {
  if (typeof text !== 'string') return undefined
  let body: unknown
  try {
    body = JSON.parse(text)
  } catch {
    return undefined
  }
  if (!isRecord(body)) return undefined
  const id = commandId(body.id)
  if (id === undefined) return undefined
  const payload = isRecord(body.payload) ? body.payload : {}
  if (body.kind === 'stop') return { id, kind: 'stop' }
  if (body.kind === 'prompt') {
    const text = payload.text
    if (typeof text !== 'string' || text.trim() === '') return { id, kind: 'invalid', reason: 'prompt without text' }
    return { id, kind: 'prompt', text, asUser: payload.asUser === true }
  }
  if (body.kind === 'message') {
    const { to, text } = payload
    if (typeof to !== 'string' || to.trim() === '') return { id, kind: 'invalid', reason: 'message without a recipient' }
    if (typeof text !== 'string' || text.trim() === '') return { id, kind: 'invalid', reason: 'message without text' }
    return { id, kind: 'message', to: to.trim(), text }
  }
  return { id, kind: 'invalid', reason: `unknown command kind: ${String(body.kind).slice(0, 40)}` }
}

export type Ack = { readonly result: 'done' | 'failed'; readonly message?: string }

export const done = (message?: string): Ack => (message === undefined ? { result: 'done' } : { result: 'done', message })
export const failed = (message: string): Ack => ({ result: 'failed', message })

export const ackBody = (ack: Ack): string =>
  JSON.stringify(ack.message === undefined ? { result: ack.result } : { result: ack.result, message: ack.message.slice(0, MAX_ACK_MESSAGE) })

/** The executed commands by id, with the ack each got: a re-delivery is acked the same, never run again. */
export type Executed = ReadonlyMap<string, Ack>

/**
 * Records `ack` under `id`, keeping the newest MAX_REMEMBERED. A prompt
 * refused for a running turn is not recorded: the daemon delivers it again
 * after the turn, and then it runs.
 */
export const remember = (executed: Executed, id: string, ack: Ack): Executed => {
  if (ack.result === 'failed' && ack.message === TURN_IN_PROGRESS) return executed
  const next = new Map(executed)
  next.delete(id)
  next.set(id, ack)
  const extra = next.size - MAX_REMEMBERED
  if (extra > 0) for (const old of [...next.keys()].slice(0, extra)) next.delete(old)
  return next
}

export type Action =
  | { readonly do: 'ack'; readonly ack: Ack }
  | { readonly do: 'abort'; readonly turnId: string }
  | { readonly do: 'submit'; readonly text: string; readonly asUser: boolean }
  | { readonly do: 'message'; readonly to: string; readonly text: string }

/** The ack for a `message` command while the `swarm` option is off. */
export const SWARM_OFF = 'swarm option is off'

/**
 * What to do with a delivered command, given the commands already executed,
 * the main loop's running turn (`turn.start`'s id, until its
 * `turn.complete`), and whether the `swarm` option is on. A `message` is sent
 * whether or not a turn runs: it lands in the recipient's queue, not this one.
 */
export const decide = (command: Command, executed: Executed, runningTurnId: string | undefined, isSwarmOn = false): Action => {
  const previous = executed.get(command.id)
  if (previous !== undefined) return { do: 'ack', ack: previous }
  switch (command.kind) {
    case 'invalid':
      return { do: 'ack', ack: failed(command.reason) }
    case 'message':
      return isSwarmOn ? { do: 'message', to: command.to, text: command.text } : { do: 'ack', ack: failed(SWARM_OFF) }
    case 'stop':
      return runningTurnId === undefined ? { do: 'ack', ack: done('no turn running') } : { do: 'abort', turnId: runningTurnId }
    case 'prompt':
      return runningTurnId === undefined
        ? { do: 'submit', text: command.text, asUser: command.asUser }
        : { do: 'ack', ack: failed(TURN_IN_PROGRESS) }
  }
}

/** A one-line, bounded reason for an ack or a log line. */
export const shortError = (error: unknown): string => {
  const text = error instanceof Error ? error.message : String(error)
  return (text.split('\n')[0] ?? '').slice(0, 160) || 'unknown error'
}

/** Whether a rejected `$.prompt.submit` says a turn is running. */
export const isTurnRunning = (error: unknown): boolean =>
  /\bturn\b.*\b(running|in progress|active|busy)\b|\bnot idle\b|\bbusy\b/i.test(shortError(error))

/** The ack for a `$.prompt.submit` that rejected. */
export const submitFailure = (error: unknown): Ack => (isTurnRunning(error) ? failed(TURN_IN_PROGRESS) : failed(shortError(error)))

/** The ack for a `$.session.send` that delivered nothing. */
export const undeliverable = (reason: string): Ack => failed(`undeliverable: ${shortError(reason)}`)

/** The ack for a `$.prompt.submit` a hook answered with `{ drop }`: the same rule, the reason marked as a drop. */
export const dropAck = (reason: string): Ack => (isTurnRunning(reason) ? failed(TURN_IN_PROGRESS) : failed(`dropped: ${shortError(reason)}`))

files.hooks/lib/forecast.ts:
// The turn forecast loop (option `forecast`). Pure: every function takes the
// loop's state or a raw value and returns the next state or a payload. The
// `$` calls (the model call, the push into the sensor queue) are spelled in
// register.ts. The wire shapes are the link protocol's `turn.forecast` and
// `turn.actual` (tools/swarmery/docs/mods-link-protocol.md): paths and numbers
// only, never prompt text, tool input or model reply text.

/** The model asked: an alias the engine resolves like `--model`. */
export const FORECAST_MODEL = 'haiku'
/** The reply's token cap: a forecast is one short JSON object. */
export const FORECAST_MAX_TOKENS = 300
/** The model call's own time limit; past it the call resolves `aborted`. */
export const FORECAST_TIMEOUT_MS = 20_000
/** The most of the user's text the model is shown. */
export const PROMPT_TEXT_LIMIT = 2_000
/** Completed turns whose touched files the model is shown. */
export const HISTORY_TURNS = 3
/** The daemon's limits on `files`. */
export const MAX_FILES = 50
export const MAX_PATH = 300
/** Random base36 characters after a run id's time: enough that two loads in the same millisecond differ. */
export const RUN_ID_RANDOM = 6

/** A Bash command that runs tests (the protocol's pattern). */
export const TEST_COMMAND = /\b(test|vitest|jest|go test|pytest|cargo test|npm (run )?test)\b/

/** Tools whose input names the file they write, and the field that names it. */
export const FILE_TOOLS: Readonly<Record<string, string>> = {
  Edit: 'file_path',
  Write: 'file_path',
  MultiEdit: 'file_path',
  NotebookEdit: 'notebook_path',
}

/** What the model claimed about the coming turn; null where it made no claim. */
export type Claims = {
  readonly files: readonly string[]
  readonly testsPass: boolean | null
  readonly steps: number | null
  readonly confidence: number | null
}

export const NO_CLAIMS: Claims = { files: [], testsPass: null, steps: null, confidence: null }

/** What the main loop did this turn, from its tool calls. */
export type Journal = {
  readonly files: readonly string[]
  readonly testsRan: boolean
  readonly testsPass: boolean | null
  readonly steps: number
}

export const EMPTY_JOURNAL: Journal = { files: [], testsRan: false, testsPass: null, steps: 0 }

/** The loop's state for one load of the module. */
export type ForecastState = {
  /**
   * Names this run of the turn counter; renewed with every reset (session.start,
   * a /clear, an in-process resume). A `--resume` keeps the session id and counts
   * from 1 again, so the daemon keys a turn on (session, runId, turnSeq).
   * '' before the first reset: no turn is forecast without one.
   */
  readonly runId: string
  /** The main loop's turn count since the run started. */
  readonly turnSeq: number
  /** Bumped on every reset, so a forecast in flight from before it does not reopen the gate. */
  readonly generation: number
  /** The running main-loop turn's id; undefined between turns. */
  readonly turnId: string | undefined
  /** This turn asked the model, so its actual is sent. */
  readonly isForecasted: boolean
  /** A forecast call is still in flight: the next turn is not forecast. */
  readonly isOpen: boolean
  readonly journal: Journal
  /** Files touched per completed turn, newest last, at most HISTORY_TURNS. */
  readonly history: ReadonlyArray<readonly string[]>
}

export const INITIAL_FORECAST: ForecastState = {
  runId: '',
  turnSeq: 0,
  generation: 0,
  turnId: undefined,
  isForecasted: false,
  isOpen: false,
  journal: EMPTY_JOURNAL,
  history: [],
}

/**
 * The state after session.start, a session.end with reason `clear`, or the
 * resync after an in-process resume: numbering starts over under `runId`.
 */
export const resetForecast = (state: ForecastState, runId: string): ForecastState => ({
  ...INITIAL_FORECAST,
  runId,
  generation: state.generation + 1,
})

/**
 * A run id: the reset's time in ms since the epoch, then `-` and RUN_ID_RANDOM
 * base36 characters drawn from `random` when there is a random source, the
 * time alone when there is none. Always within the daemon's
 * `[A-Za-z0-9._:-]{1,64}`.
 */
export const runIdOf = (nowMs: number, random: Uint8Array | undefined): string => {
  const ms = Number.isFinite(nowMs) && nowMs >= 0 ? Math.floor(nowMs) : 0
  const time = String(ms)
  if (random === undefined || random.length < RUN_ID_RANDOM) return time
  const tail = Array.from(random.subarray(0, RUN_ID_RANDOM), b => (b % 36).toString(36)).join('')
  return `${time}-${tail}`
}

/**
 * Whether a turn's text was typed by the person: empty text (a continuation)
 * and the forms a command or a notification arrives in are not.
 */
export const isUserText = (text: string): boolean => {
  const t = text.trim()
  return t !== '' && !/^(\/|<(command-|local-command|task-notification|system-reminder))/.test(t)
}

/** The state at a main-loop turn.start, and whether to ask the model for this turn. */
export const startTurn = (
  state: ForecastState,
  turnId: string,
  text: string,
  canSend: boolean,
): { readonly state: ForecastState; readonly shouldAsk: boolean } => {
  const shouldAsk = canSend && state.runId !== '' && !state.isOpen && isUserText(text)
  return {
    shouldAsk,
    state: {
      ...state,
      turnSeq: state.turnSeq + 1,
      turnId,
      isForecasted: shouldAsk,
      isOpen: state.isOpen || shouldAsk,
      journal: EMPTY_JOURNAL,
    },
  }
}

/** The state once the forecast call of `generation` settled. */
export const closeForecast = (state: ForecastState, generation: number): ForecastState =>
  state.generation === generation ? { ...state, isOpen: false } : state

/**
 * The state at the main loop's turn.complete, and the turn.actual payload when
 * the turn was forecast. The actual carries the run the turn started in: a
 * reset between start and complete clears `turnId`, so no actual is built
 * across one.
 */
export const endTurn = (
  state: ForecastState,
  turnId: string,
): { readonly state: ForecastState; readonly actual: Readonly<Record<string, unknown>> | undefined } => {
  if (state.turnId === undefined || state.turnId !== turnId) return { state, actual: undefined }
  const { journal } = state
  const actual = state.isForecasted
    ? { runId: state.runId, turnSeq: state.turnSeq, files: journal.files, testsRan: journal.testsRan, testsPass: journal.testsPass, steps: journal.steps }
    : undefined
  return {
    actual,
    state: {
      ...state,
      turnId: undefined,
      isForecasted: false,
      journal: EMPTY_JOURNAL,
      history: [...state.history, journal.files].slice(-HISTORY_TURNS),
    },
  }
}

/** `path` with `./`, duplicate and trailing separators gone, relative to `cwd` when under it. */
export const normalizePath = (path: string, cwd: string): string => {
  const clean = (p: string): string =>
    p
      .trim()
      .replace(/\/{2,}/g, '/')
      .replace(/^(\.\/)+/, '')
      .replace(/(.)\/$/, '$1')
  const p = clean(path)
  const root = clean(cwd)
  return root !== '' && root !== '/' && p.startsWith(`${root}/`) ? p.slice(root.length + 1) : p
}

/**
 * Whether `p` can stand on the wire as a path: one token of at most MAX_PATH
 * characters naming a directory or an extension. A model that echoes prose
 * into `files` has it dropped here, so prompt text never rides along.
 */
const isWirePath = (p: string): boolean =>
  p.length > 0 && p.length <= MAX_PATH && !/[\s\u0000-\u001f<>"'`|;]/.test(p) && /[./]/.test(p)

/** The paths added to `files` in order, each once, valid ones only, at most MAX_FILES. */
const addFiles = (files: readonly string[], more: readonly string[]): readonly string[] => {
  const out = [...files]
  for (const p of more) {
    if (out.length >= MAX_FILES) break
    if (isWirePath(p) && !out.includes(p)) out.push(p)
  }
  return out
}

/** A tool call as the journal reads it: the tool, its loop, and the input fields it may name. */
export type ToolCallFacts = {
  readonly tool: string
  readonly agentId?: string | undefined
  readonly fields: Readonly<Record<string, unknown>>
}

/** How the call ended, from `next(e)`'s result. */
export type ToolOutcome = 'ok' | 'error' | 'denied'

/**
 * The journal after one tool call of the running turn ended with `outcome`.
 * A subagent's call (agentId present), or a call outside a turn, leaves it as
 * it was. Every main-loop call is a step; a file counts once its write
 * succeeded; a test command run in the foreground sets testsRan and testsPass
 * (the last one wins: a red run fixed later in the turn reads as passing).
 */
export const noteToolCall = (state: ForecastState, call: ToolCallFacts, outcome: ToolOutcome, cwd: string): ForecastState => {
  if (state.turnId === undefined || call.agentId !== undefined) return state
  let journal: Journal = { ...state.journal, steps: state.journal.steps + 1 }
  const field = FILE_TOOLS[call.tool]
  const target = field === undefined ? undefined : call.fields[field]
  if (typeof target === 'string' && outcome === 'ok') {
    journal = { ...journal, files: addFiles(journal.files, [normalizePath(target, cwd)]) }
  }
  const command = call.tool === 'Bash' ? call.fields.command : undefined
  if (typeof command === 'string' && TEST_COMMAND.test(command) && outcome !== 'denied') {
    const isBackground = call.fields.run_in_background === true
    journal = { ...journal, testsRan: true, testsPass: isBackground ? journal.testsPass : outcome === 'ok' }
  }
  return { ...state, journal }
}

/** The model's request: a short fixed instruction, the user's text and the files of the last turns. */
export const forecastRequest = (text: string, history: ReadonlyArray<readonly string[]>): { readonly system: string; readonly prompt: string } => {
  const recent = [...new Set(history.flat())]
  const shown = text.length > PROMPT_TEXT_LIMIT ? `${text.slice(0, PROMPT_TEXT_LIMIT)}…` : text
  return {
    system: [
      'You forecast what a coding agent will do while it answers the request below.',
      'Reply with one JSON object and nothing else:',
      '{"files": [paths it will create or edit, relative to the repository root], "testsPass": true | false | null (null when it will not run tests),',
      '"steps": number of tool calls it will make, "confidence": 0..1 that the forecast is right}.',
    ].join(' '),
    prompt: [
      'Request:',
      shown,
      '',
      'Files edited in the previous turns:',
      recent.length > 0 ? recent.map(p => `- ${p}`).join('\n') : '(none)',
    ].join('\n'),
  }
}

/** The first balanced `{...}` in `text`, strings respected; undefined when there is none. */
const firstObject = (text: string): string | undefined => {
  const start = text.indexOf('{')
  if (start < 0) return undefined
  let depth = 0
  let inString = false
  let escaped = false
  for (let i = start; i < text.length; i += 1) {
    const c = text[i]
    if (inString) {
      if (escaped) escaped = false
      else if (c === '\\') escaped = true
      else if (c === '"') inString = false
      continue
    }
    if (c === '"') inString = true
    else if (c === '{') depth += 1
    else if (c === '}') {
      depth -= 1
      if (depth === 0) return text.slice(start, i + 1)
    }
  }
  return undefined
}

const isRecord = (v: unknown): v is Readonly<Record<string, unknown>> => typeof v === 'object' && v !== null && !Array.isArray(v)

/**
 * The claims in a model reply: the first JSON object in it, each field held to
 * the protocol's limits; a field out of shape is null, a reply with no
 * readable object is NO_CLAIMS.
 */
export const parseForecast = (reply: string | undefined, cwd: string): Claims => {
  const raw = reply === undefined ? undefined : firstObject(reply)
  if (raw === undefined) return NO_CLAIMS
  let value: unknown
  try {
    value = JSON.parse(raw)
  } catch {
    return NO_CLAIMS
  }
  if (!isRecord(value)) return NO_CLAIMS
  const files = Array.isArray(value.files)
    ? addFiles(
        [],
        value.files.filter((f): f is string => typeof f === 'string').map(f => normalizePath(f, cwd)),
      )
    : []
  const steps = typeof value.steps === 'number' && Number.isFinite(value.steps) ? Math.max(0, Math.round(value.steps)) : null
  const confidence =
    typeof value.confidence === 'number' && Number.isFinite(value.confidence) ? Math.min(1, Math.max(0, value.confidence)) : null
  return {
    files,
    testsPass: typeof value.testsPass === 'boolean' ? value.testsPass : null,
    steps,
    confidence,
  }
}

/** The four token counts of a model call, as ModelUsage spells them. */
export type TokenUsage = {
  readonly input_tokens: number
  readonly output_tokens: number
  readonly cache_read_input_tokens: number
  readonly cache_creation_input_tokens: number
}

/** Every token the call was billed for, input (cached or not) and output; null when the reply carried no usage. */
export const usageTokens = (usage: TokenUsage | undefined): number | null => {
  if (usage === undefined) return null
  const sum = usage.input_tokens + usage.output_tokens + usage.cache_read_input_tokens + usage.cache_creation_input_tokens
  return Number.isFinite(sum) && sum >= 0 ? Math.round(sum) : null
}

/** The turn.forecast payload; `runId` is the run the forecast turn started in. */
export const forecastPayload = (
  runId: string,
  turnSeq: number,
  claims: Claims,
  model: string,
  forecastTokens: number | null,
): Readonly<Record<string, unknown>> => ({
  runId,
  turnSeq,
  files: claims.files,
  testsPass: claims.testsPass,
  steps: claims.steps,
  confidence: claims.confidence,
  model: model.slice(0, 80),
  forecastTokens,
})

